<section class="dashboard-charts" aria-label="Application charts" data-chart-data="<?= e(json_encode($charts, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT)) ?>">
    <article class="chart-panel"><div><p class="eyebrow">Intake trend</p><h2>Applications over time</h2></div><canvas data-chart="monthly" aria-label="Applications submitted by month" role="img"></canvas><p class="visually-hidden">Monthly application data: <?php foreach ($charts['monthly'] as $item): ?><?= e($item['month_key']) ?> <?= (int) $item['total'] ?>; <?php endforeach; ?></p></article>
    <article class="chart-panel"><div><p class="eyebrow">Current workload</p><h2>Application statuses</h2></div><canvas data-chart="statuses" aria-label="Application count by status" role="img"></canvas><p class="visually-hidden">Status data: <?php foreach ($charts['statuses'] as $item): ?><?= e($item['status']) ?> <?= (int) $item['total'] ?>; <?php endforeach; ?></p></article>
    <article class="chart-panel chart-panel-wide"><div><p class="eyebrow">Program demand</p><h2>Applications by program</h2></div><canvas data-chart="programs" aria-label="Application count by academic program" role="img"></canvas><p class="visually-hidden">Program data: <?php foreach ($charts['programs'] as $item): ?><?= e($item['label']) ?> <?= (int) $item['total'] ?>; <?php endforeach; ?></p></article>
    <article class="chart-panel"><div><p class="eyebrow">Submission and review activity</p><h2>Submitted vs. reviewed</h2><p class="chart-description">Monthly counts. A review is the first transition into screening.</p></div><canvas data-chart="submitted-reviewed" aria-label="Submitted and first-reviewed applications by month" role="img"></canvas><p class="visually-hidden">Submitted and reviewed data by month: <?php foreach ($charts['submitted_reviewed'] as $item): ?><?= e($item['month_key']) ?> submitted <?= (int) $item['submitted'] ?> reviewed <?= (int) $item['reviewed'] ?>; <?php endforeach; ?></p></article>
    <article class="chart-panel"><div><p class="eyebrow">Open intake<?= !empty($charts['intake_progress']['intake']['label']) ? ' · ' . e($charts['intake_progress']['intake']['label']) : '' ?></p><h2>Intake progress</h2><p class="chart-description">Current application counts by workflow status. Counts are not a completion percentage.</p></div><canvas data-chart="intake-progress" aria-label="Current application counts by status for the open intake" role="img"></canvas><?php if (!empty($charts['intake_progress']['intake'])): ?><p class="visually-hidden">Current intake status counts: <?php foreach ($charts['intake_progress']['stages'] as $item): ?><?= e($item['label']) ?> <?= (int) $item['total'] ?>; <?php endforeach; ?></p><?php endif; ?></article>
    <article class="chart-panel chart-panel-wide"><div><p class="eyebrow">First review timing</p><h2>Review-time summary</h2><p class="chart-description">Average elapsed time from submission to first screening, by review month, in hours.</p></div><canvas data-chart="review-time" aria-label="Average hours from submission to first screening, by month" role="img"></canvas><p class="visually-hidden">Average review time in hours by month: <?php foreach ($charts['review_time'] as $item): ?><?= e($item['month_key']) ?> <?= $item['average_hours'] === null ? 'no review data' : e(number_format((float) $item['average_hours'], 1) . ' hours') ?>; <?php endforeach; ?></p></article>
</section>